int8_t conv34(
    const int8_t matrix_input[34],  // 输入数据（int8）
    const int8_t matrix_w[34],      // 卷积核权重（int8）
    int32_t M0,                    // 定点乘数（Q31 格式）
    int32_t shift,                 // 移位指数（非负整数）
    int32_t Z1,                     // 输入零点偏移（int8）,对应input
    int32_t Z3,                     // 输出零点偏移（int8），对应output
    int32_t bias                    // 新增的32位偏置项（int32）
) {
#pragma HLS INLINE

	const int BLOCK_SIZE = 2; // 34/2=17，选择能整除34的因子
	int32_t p_blocks[BLOCK_SIZE] = {0}; // 用32位累加器（足够）

    // Step 1: 计算点积（考虑输入零点偏移）
    for (int i = 0; i < 34; i++) {
#pragma HLS UNROLL factor=BLOCK_SIZE
    	int idx = i % BLOCK_SIZE;
        int16_t input_val = (int16_t)(matrix_input[i] - Z1);
        int16_t weight_val = (int16_t)matrix_w[i];
        p_blocks[idx] += input_val * weight_val; // 32位累加

    }

    // 合并分块结果（64位仅此处使用）
    int64_t p = 0;
    for (int b = 0; b < BLOCK_SIZE; b++) {
        p += p_blocks[b];
    }

    // Step 2: 定点乘法与四舍五入右移（对点积结果p）,计算偏置项bis的定点结果（同样四舍五入）
    int64_t temp = (p +bias)* M0;                    // int64乘法
    temp += (1LL << (shift - 1));            // 四舍五入补偿
    temp = temp >> shift;                    // 右移操作

    // Step 3: 合并结果并添加输出零点偏移
    int64_t out = temp + Z3;


    // Step 4: 饱和处理到int8范围 [-128, 127]
    if (out >= 127) {
        out = 127;
    }
    else if (out <= -128) {
        out = -128;
    }

    return (int8_t)out;
}



int8_t mult_conv34(
    const int8_t matrix_input[][34],  // 输入数据（int8）
    const int8_t matrix_w[][34],      // 卷积核权重（int8）
    int32_t M0,                    // 定点乘数（Q31 格式）
    int32_t shift,                 // 移位指数（非负整数）
    int32_t Z1,                     // 输入零点偏移（int8）,对应input
    int32_t Z3,                     // 输出零点偏移（int8），对应output
    int32_t bias,                    // 新增的32位偏置项（int32）
	int num_channels                //输入通道数
) {
#pragma HLS INLINE
	int64_t total_p = 0;
    for (int ch = 0; ch < num_channels; ++ch) {
#pragma HLS UNROLL factor=2
    	int64_t p = 0;  // 累加器（int64_t，防止溢出）
    	// Step 1: 计算点积（考虑输入零点偏移）
    	for (int i = 0; i < 34; i++) {
#pragma HLS UNROLL factor=4
    		int16_t input_val = (int16_t)(matrix_input[ch][i] - Z1);
    		int16_t weight_val = (int16_t)matrix_w[ch][i];
    		ap_int<32> partial = (int64_t)input_val * weight_val;  // int32累加

    		p+=partial;
//    		p += (int64_t)input_val * weight_val;  // int32累加
    	}
    	total_p += p;
    }

    // Step 2: 定点乘法与四舍五入右移（对点积结果p）,计算偏置项bis的定点结果（同样四舍五入）
    int64_t temp = (total_p + bias)* M0;                    // int64乘法
    temp += (1LL << (shift - 1));            // 四舍五入补偿
    temp = temp >> shift;                    // 右移操作

    // Step 3: 合并结果并添加输出零点偏移
    int64_t out = temp + Z3;


    // Step 4: 饱和处理到int8范围 [-128, 127]
    if (out >= 127) {
        out = 127;
    }
    else if (out <= -128) {
        out = -128;
    }

    return (int8_t)out;
}



