void conv_layer1(
    const int8_t input[864],
    const int8_t weights_1[16][34],
    const int32_t M_1[16],
	const int32_t shift_1[16],
    const int32_t bias_1[16],
	int8_t output_1[16][831]

) {

#pragma HLS ARRAY_PARTITION variable=output_1 cyclic factor=2 dim=1


    for (int oc = 0; oc < 16; ++oc) {

      //每个输出通道   oc为输出通道，ic为输入通道
        for (int pos = 0; pos < 831; ++pos) {  // 每个输出位置
#pragma HLS UNROLL factor=3
        	int8_t input_fragment[34];
        	int8_t weight[34];

        	for (int k = 0; k < 34; ++k) {  //每个卷积核大小
#pragma HLS PIPELINE II=2
#pragma HLS UNROLL factor=2
        		input_fragment[k] = input[pos + k];
        		weight[k]=weights_1[oc][k];
        	}

        	output_1[oc][pos] = conv34(
        	                    input_fragment,      // 输入片段
								weight,     // 当前通道权重
        	                    M_1[oc], shift_1[oc], -128, -128, bias_1[oc] // 注意bis设为0，最后统一加偏置
        	);

         }
    }

}
