const int32_t M_4[8] = {1018,615,625,754,571,934,830,997};
const int32_t shift_4[8] = {19,18,18,19,18,19,19,19};
const int32_t bias_4[8] = {31528, 8918, -3363, 2279, 16357, -4004, 138, 5080};


void conv_layer4(
		const int8_t input[8][399],
		const int8_t weights_4[8][8][34],
		const int32_t M_4[8],
		const int32_t shift_4[8],
		const int32_t bias_4[8],
	int8_t output_4[8][366]
) {
#pragma HLS ARRAY_PARTITION variable=input cyclic factor=2 dim=1
#pragma HLS ARRAY_PARTITION variable=output_4 cyclic factor=2 dim=1
    for (int oc = 0; oc < 8; ++oc) { //每个输出通道   oc为输出通道，ic为输入通道

    	for (int pos = 0; pos < 366; ++pos) {  // 每个输出位置
#pragma HLS UNROLL factor=2 // 展开输出通道循环
    		int8_t input_segments[8][34];
        	int8_t weight[8][34];
        	for (int ic = 0; ic < 8; ++ic) { //每个输入通道
#pragma HLS UNROLL factor=4 // 展开输出通道循环
        		for (int k = 0; k < 34; ++k) {  //每个卷积核大小
        			input_segments[ic][k] = input[ic][pos + k];
        			weight[ic][k] = weights_4[oc][ic][k];
        		}
        	}
        	output_4[oc][pos] = mult_conv34(
        			            input_segments,      // 输入片段
        	        	        weight,     // 当前通道权重
        	        	        M_4[oc], shift_4[oc],
								-128, -128, bias_4[oc],
								8// 注意bis设为0，最后统一加偏置
            );

        }
    }

}


void pooling_layer5(
		const int8_t input[8][366],
		int8_t output_5[8][183]
) {
    for (int ch = 0; ch < 8; ++ch) {
#pragma HLS UNROLL factor=2 // 展开通道循环
        for (int i = 0, index = 0; i < 366; i+=2, index++) {
        	output_5[ch][index] = std::max(input[ch][i], input[ch][i+1]);
        }
    }
}
