const int32_t M_6[4] = {629,633,828,874};
const int32_t shift_6[4] = {18,18,18,19};
const int32_t bias_6[4] = {-10745, -10152, -4688, 22791};


void conv_layer6(
		const int8_t input[8][183],
		const int8_t weights_6[4][8][34],
		const int32_t M_6[4],
		const int32_t shift_6[4],
		const int32_t bias_6[4],
	int8_t output_6[4][150]
) {
#pragma HLS ARRAY_PARTITION variable=input cyclic factor=2 dim=1
#pragma HLS ARRAY_PARTITION variable=output_6 cyclic factor=2 dim=1
    for (int oc = 0; oc < 4; ++oc) { //每个输出通道   oc为输出通道，ic为输入通道

    	for (int pos = 0; pos < 150; ++pos) {  // 每个输出位置
#pragma HLS UNROLL factor=2 // 展开输出通道循环
    		int8_t input_segments[8][34];
        	int8_t weight[8][34];
        	for (int ic = 0; ic < 8; ++ic) { //每个输入通道
#pragma HLS UNROLL factor=4 // 展开输出通道循环
        		for (int k = 0; k < 34; ++k) {  //每个卷积核大小
        			input_segments[ic][k] = input[ic][pos + k];
        			weight[ic][k] = weights_6[oc][ic][k];
        		}
        	}
        	output_6[oc][pos] = mult_conv34(
        			            input_segments,      // 输入片段
        	        	        weight,     // 当前通道权重
        	        	        M_6[oc], shift_6[oc],
								-128, -128, bias_6[oc],
								8// 注意bis设为0，最后统一加偏置
            );

        }
    }

}


void pooling_layer7(
	const int8_t input[4][150],
	int8_t output_7[4][75]
) {
    for (int ch = 0; ch < 4; ++ch) {
#pragma HLS UNROLL factor=2 // 展开通道循环
        for (int i = 0, index = 0; i < 150; i+=2, index++) {
        	output_7[ch][index] = std::max(input[ch][i], input[ch][i+1]);
        }
    }
}



void reshape_layer8(
    const int8_t input[4][75],
	int8_t output_8[300]
) {
    int idx = 0;
    for (int i = 0; i < 75; ++i) {
#pragma HLS UNROLL factor=3 // 展开通道循环
        for (int ch = 0; ch < 4; ++ch) {
            output_8[idx++] = input[ch][i];
        }
    }
}

