const int32_t bias_9[64] = { -102, 341, 102, 422, 490, 338, -497, 121, -469, -20, 782, 156, -3, 518, -385, 529, 229, 1223, -457, 374, -78, 282, 189, 267, 1125, 1985, 1288, 143, 372, -453, -429, 95, -52, 237, -248, 127, -186, 1099, 133, 112, 424, 144, 116, 119, -544, -539, -423, -273, 284, -104, -546, 1296, -278, -249, 401, -347, -100, 236, -292, 176, 591, -4, 581, 1008};
const int32_t M_9	= 518;
const int32_t shift_9 = 19;


void dense_layer9(
    const int8_t input[300],  // 输入数据（int8）
    const int8_t weights_9[64][300],      // 卷积核权重（int8）
	const int32_t bias_9[64],        //偏置
    int32_t M_9,                    // 定点乘数（Q31 格式）
    int32_t shift_9,                 // 移位指数（非负整数）
	int8_t output_9[64]
) {
#pragma HLS ARRAY_PARTITION variable=input cyclic factor=2
#pragma HLS ARRAY_PARTITION variable=output_9 cyclic factor=2
    for (int ch = 0; ch < 64; ++ch) {

    	const int BLOCK_SIZE = 4; // 每块75次迭代 (300/4=75)
    	int32_t p_blocks[BLOCK_SIZE] = {0}; // 用32位累加器（足够）

    	// Step 1: 计算点积（考虑输入零点偏移）
    	for (int i = 0; i < 300; i++) {
#pragma HLS PIPELINE II=2 // 实现单周期吞吐
#pragma HLS UNROLL factor=4 // 与BLOCK_SIZE匹配
    		int idx = i % BLOCK_SIZE;
    		int16_t input_val = (int16_t)(input[i] + 128);
    		int16_t weight_val = (int16_t)weights_9[ch][i];
    		p_blocks[idx] += input_val * weight_val; // 32位累加

    	}
    	// 合并分块结果（64位仅此处使用）
    	int64_t p = 0;
    	for (int b = 0; b < BLOCK_SIZE; b++) {
    	    p += p_blocks[b];
    	}


    	// Step 2: 定点乘法与四舍五入右移（对点积结果p）,计算偏置项bis的定点结果（同样四舍五入）
    	int64_t temp = (p + bias_9[ch])* M_9;      // int64乘法
    	temp += (1LL << (shift_9 - 1));            // 四舍五入补偿
    	temp = temp >> shift_9;                    // 右移操作


    	// Step 3: 合并结果并添加输出零点偏移
    	int64_t out = temp - 128;

    	// Step 4: 饱和处理到int8范围 [-128, 127]
    	if (out >= 127) {
    		out = 127;
    	}
    	else if (out <= -128) {
    		out = -128;
    	}
    	output_9[ch] = out;
    }

}

