const int32_t bias_10[4] = {-70, 45, -171, 213};
const int32_t M_10 = 602;
const int32_t shift_10 = 19;


void dense_layer10(
    const int8_t input[64],  // 输入数据（int8）
    const int8_t weights_10[4][64],      // 卷积核权重（int8）
	const int32_t bias_10[4],        //偏置
    int32_t M_10,                    // 定点乘数（Q31 格式）
    int32_t shift_10,                // 移位指数（非负整数）
	int8_t output_10[4]
) {

    for (int ch = 0; ch < 4; ++ch) {
#pragma HLS UNROLL factor=4 // 展开输出通道循环
    	int64_t p = 0;  // 累加器（int64_t，防止溢出）

    	// Step 1: 计算点积（考虑输入零点偏移）
    	for (int i = 0; i < 64; i++) {
#pragma HLS PIPELINE II=1 // 实现单周期吞吐
    		int16_t input_val = (int16_t)(input[i] + 128);
    		int16_t weight_val = (int16_t)weights_10[ch][i];
    		p += (int64_t)input_val * weight_val;  // int32累加
    	}
    	// Step 2: 定点乘法与四舍五入右移（对点积结果p）,计算偏置项bis的定点结果（同样四舍五入）
    	int64_t temp = (p + bias_10[ch])* M_10;                    // int64乘法
    	temp += (1LL << (shift_10 - 1));            // 四舍五入补偿
    	temp = temp >> shift_10;                    // 右移操作

    	// Step 3: 合并结果并添加输出零点偏移
    	output_10[ch] = temp - 1;
    	// Step 4: 饱和处理到int8范围 [-128, 127]
    	if (output_10[ch] >= 127) {
    		output_10[ch] = 127;
    	}
    	else if (output_10[ch] <= -128) {
    		output_10[ch] = -128;
    	}
    }

}

int argmax_layer11(
    const int8_t input[4] // 输入数据（int8）
) {
	int index;
	int max_index = 0;
	for(index = 0; index < 4; index++ ){
		if (input[index] > input[max_index]) {
			max_index = index;
		}
	}
	return max_index;
}


void d_cnn_3(hls::stream<int8_t> &input_stream,
		int *result
) {


#pragma HLS INTERFACE s_axilite port=result
#pragma HLS INTERFACE s_axilite port=return  // 必须添加！
#pragma HLS INTERFACE axis port=input_stream


#pragma HLS DATAFLOW // 实现任务级流水线

	// 数组分区优化
#pragma HLS ARRAY_PARTITION variable=weights_1 cyclic factor=2 dim=1
#pragma HLS ARRAY_PARTITION variable=weights_2 cyclic factor=1 dim=1
#pragma HLS ARRAY_PARTITION variable=weights_4 cyclic factor=1 dim=1
#pragma HLS ARRAY_PARTITION variable=weights_6 cyclic factor=1 dim=1
#pragma HLS ARRAY_PARTITION variable=weights_9 cyclic factor=2 dim=1
#pragma HLS ARRAY_PARTITION variable=weights_10 cyclic factor=1 dim=1


	static int8_t input_data[864];
	static int8_t output_1[16][831];
	static int8_t output_2[8][798];
	static int8_t output_3[8][399];
	static int8_t output_4[8][366];
	static int8_t output_5[8][183];
	static int8_t output_6[4][150];
	static int8_t output_7[4][75];
	static int8_t output_8[300];
	static int8_t output_9[64];
	static int8_t output_10[4];


    // 从流中读取输入数据
    for (int i = 0; i < 864; ++i) {
        #pragma HLS PIPELINE II=1
        input_data[i] = input_stream.read();
    }



    // 第1层卷积
	conv_layer1(input_data,
               weights_1,
               M_1,
               shift_1,
               bias_1,
			   output_1);



    // 第2层卷积
    conv_layer2(output_1,
               weights_2,
               M_2,
               shift_2,
               bias_2,
			   output_2);



    // 第3层池化
    pooling_layer3(output_2,output_3);


    // 第4层卷积
    conv_layer4(output_3,
               weights_4,
               M_4,
               shift_4,
               bias_4,
			   output_4);


    // 第5层池化
    pooling_layer5(output_4,output_5);

    // 第6层卷积
    conv_layer6(output_5,
               weights_6,
               M_6,
               shift_6,
               bias_6,
			   output_6);



    // 第7层池化
    pooling_layer7(output_6,output_7);

    // 第8层展平
    reshape_layer8(output_7,output_8);


    // 第9层全连接
    dense_layer9(output_8,
                weights_9,
                bias_9,
                M_9,
                shift_9,
				output_9);


    // 第10层全连接
    dense_layer10(output_9,
                 weights_10,
                 bias_10,
                 M_10,
                 shift_10,
				 output_10);


    // 第11层softmax
    *result = argmax_layer11(output_10);
}


